{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[],"toc_visible":true,"authorship_tag":"ABX9TyNeK0H/mP6qbc0R2Q7pdZ5S"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","execution_count":1,"metadata":{"colab":{"base_uri":"https://localhost:8080/"},"id":"YtgYd2RCjUgn","executionInfo":{"status":"ok","timestamp":1781095334257,"user_tz":240,"elapsed":703,"user":{"displayName":"Miranda Pachini","userId":"17695548108147911939"}},"outputId":"34735810-8779-47d8-ab85-ccd2ea153be1"},"outputs":[{"output_type":"stream","name":"stdout","text":["CSV created: environmental_data.csv\n"]}],"source":["import requests\n","import csv\n","import datetime\n","\n","# --- Open-Meteo URL ---\n","url = (\n","    \"https://api.open-meteo.com/v1/forecast\"\n","    \"?latitude=38.2527\"\n","    \"&longitude=-85.7585\"\n","    \"&timezone=America/New_York\"\n","    \"&hourly=temperature_2m,wind_speed_10m,precipitation_probability,\"\n","    \"soil_temperature_0cm,soil_moisture_0_to_1cm,pm2_5,ozone,us_aqi,\"\n","    \"grass_pollen,ragweed_pollen,birch_pollen,alder_pollen,\"\n","    \"mugwort_pollen,olive_pollen\"\n",")\n","\n","# --- Fetch data ---\n","response = requests.get(url)\n","data = response.json()\n","hourly = data[\"hourly\"]\n","times = hourly[\"time\"]\n","\n","# --- Write CSV ---\n","with open(\"environmental_data.csv\", \"w\", newline=\"\") as f:\n","    writer = csv.writer(f)\n","\n","    # Header\n","    writer.writerow([\n","        \"datetime_id\",\n","        \"env_id\",\n","        \"temperature_2m\",\n","        \"wind_speed_10m\",\n","        \"precipitation_proabability\",\n","        \"soil_temperature_0cm\",\n","        \"soil_moisture_0_to_1cm\",\n","        \"pm25\",\n","        \"ozone\",\n","        \"us_aqi\",\n","        \"grass_pollen\",\n","        \"ragweed_pollen\",\n","        \"birch_pollen\",\n","        \"alder_pollen\",\n","        \"mugwort_pollen\",\n","        \"olive_pollen\",\n","        \"planting_readiness\",\n","        \"allergy_risk\",\n","        \"high_wind_flag\",\n","        \"rain_expected_flag\",\n","        \"soil_too_wet_flag\",\n","        \"poor_air_quality_flag\",\n","        \"high_pollen_flag\"\n","    ])\n","\n","    # Rows\n","    for i, t in enumerate(times):\n","        dt_epoch = int(datetime.datetime.fromisoformat(t).timestamp())\n","\n","        writer.writerow([\n","            dt_epoch,\n","            1,\n","            hourly[\"temperature_2m\"][i],\n","            hourly[\"wind_speed_10m\"][i],\n","            hourly[\"precipitation_probability\"][i],\n","            hourly[\"soil_temperature_0cm\"][i],\n","            hourly[\"soil_moisture_0_to_1cm\"][i],\n","            hourly[\"pm2_5\"][i],\n","            hourly[\"ozone\"][i],\n","            hourly[\"us_aqi\"][i],\n","            hourly[\"grass_pollen\"][i],\n","            hourly[\"ragweed_pollen\"][i],\n","            hourly[\"birch_pollen\"][i],\n","            hourly[\"alder_pollen\"][i],\n","            hourly[\"mugwort_pollen\"][i],\n","            hourly[\"olive_pollen\"][i],\n","            False, False, False, False, False, False, False\n","        ])\n","\n","print(\"CSV created: environmental_data.csv\")\n"]}]}
